  public startZoomDetection(): void {
    if (this._zoomPollTimer) return
    console.log('[ZoomDetector] Starting poll')

    const tick = () => {
      if (!this.isUndetectable) return
      const running = this._isZoomRunning()
      if (running && !this._launcherHiddenForZoom) {
        console.log('[ZoomDetector] Zoom detected — hiding launcher')
        this.windowHelper.hideMainWindow()
        this._launcherHiddenForZoom = true
      } else if (!running && this._launcherHiddenForZoom) {
        console.log('[ZoomDetector] Zoom closed — restoring launcher')
        this.windowHelper.showMainWindow()
        this._launcherHiddenForZoom = false
      }
    }

    tick()
    this._zoomPollTimer = setInterval(tick, 1000)
  }

  public stopZoomDetection(): void {
    if (this._zoomPollTimer) {
      clearInterval(this._zoomPollTimer)
      this._zoomPollTimer = null
    }
    if (this._launcherHiddenForZoom) {
      this.windowHelper.showMainWindow()
      this._launcherHiddenForZoom = false
    }
  }

